for (const key in row) {
  if (row[key]) {
    lastDate = row[key];
  } else if (lastDate) {
    row[key] = lastDate;
  }
}

return $input.all();

let fullName = null;

const result = items.map(item => {
  const current = item.json.col_2;

  if (current && current !== "") {
    fullName = current; // lưu tên mới
  }

  return {
    json: {
      ...item.json,
      col_2: fullName // gán tên hiện tại hoặc tên gần nhất phía trên
    }
  };
});

return result;

// 1. Làm mịn dòng ngày (items[3])
const dateRow = items[3].json;
let lastDate = null;
const dateMap = {};

for (const key in dateRow) {
  if (dateRow[key]) {
    lastDate = dateRow[key]; // giữ nguyên định dạng dd/MM/yyyy
  }
  dateMap[key] = lastDate;
}

// 2. Lấy ngày hôm nay dạng dd/MM/yyyy
const now = new Date();

// Tính giờ Việt Nam (GMT+7)
const vnOffset = 7 * 60; // phút
const localTime = new Date(now.getTime() + vnOffset * 60 * 1000);

// Format dd/MM/yyyy
const todayStr = localTime.toLocaleDateString('vi-VN', {
  day: '2-digit',
  month: '2-digit',
  year: 'numeric'
});

// 3. Lọc theo tên và ngày hôm nay
const result = [];

for (let i = 4; i < items.length; i++) {
  const row = items[i].json;

  if (row.col_2 === "Phạm Thị Hồng Điệp") {
    for (const key in row) {
      if (
        key.startsWith("col_") &&
        key !== "col_2" &&
        key !== "col_1" &&
        row[key]
      ) {
        const date = dateMap[key];

        if (date === todayStr) {
          result.push({
            json: {
              name: "Phạm Thị Hồng Điệp",
              date,
              location: row[key]
            }
          });
        }
      }
    }
  }
}

return result;

const records = $input.all(); // hoặc dùng data trực tiếp nếu cần

if (!records.length) {
  return [{ json: { subject: "Không có lịch học hôm nay", body: "Không tìm thấy dữ liệu lịch học." } }];
}

const name = records[0].json.name;
const date = records[0].json.date;

// Lấy danh sách location duy nhất
const uniqueLocations = [...new Set(records.map(item => item.json.location))];

// Tạo body
let body = `Chào bạn ${name} 👋,\n\n`;
body += `Dưới đây là lịch làm việc của bạn cho ngày ${date}:\n\n`;
uniqueLocations.forEach(location => {
  body += `- 📍 ${location}\n`;
});
body += `\nChúc bạn một ngày làm việc hiệu quả và nhiều niềm vui! 🎉`;

return [{ json: { body } }];

// Lấy ngày hôm nay
const today = new Date();
const todayTime = today.getTime();

// Hàm chuyển chuỗi "dd/mm" thành Date object cùng năm hiện tại
function parseDate(ddmm) {
  const [day, month] = ddmm.split('/').map(Number);
  return new Date(today.getFullYear(), month - 1, day);
}

const dataJson = $input.all();

// Tìm sheet có ngày hôm nay nằm trong khoảng ngày
let matchedSheet;
dataJson.find(sheets => {
  matchedSheet = sheets.json.sheets.find(sheet => {
    const title = sheet.properties.title;

    const match = title.match(/(\d{1,2}\/\d{1,2})-(\d{1,2}\/\d{1,2})/);

    if (!match) return false;

    const start = parseDate(match[1]).getTime();
    const end = parseDate(match[2]).getTime();

    return todayTime >= start && todayTime <= end;
  })
  return matchedSheet;
});

console.log('matchedSheet',matchedSheet);
// Trả ra kết quả
return [{
  json: {
    matchedTitle: matchedSheet?.properties.title || "Không tìm thấy sheet phù hợp"
  }
}];
